steps.code:
mutation {
  productCreate(input: {
    title: "Camiseta",
    variants: [{price: "49.90"}]
  }) { product { id } }
}

mutation {
  productVariantsBulkCreate(
    productId: "gid://shopify/Product/1",
    variants: [
      { price: "49.90", optionValues: [{ name: "Azul", optionName: "Cor" }] },
      { price: "49.90", optionValues: [{ name: "Vermelho", optionName: "Cor" }] }
    ]
  ) { productVariants { id } userErrors { field message } }
}

mutation {
  collectionCreate(input: {
    title: "Promoções",
    ruleSet: {
      appliedDisjunctively: false,
      rules: [{ column: TAG, relation: EQUALS, condition: "promo" }]
    }
  }) { collection { id } }
}

query {
  product(id: "gid://shopify/Product/1") {
    title
    variants(first: 10) {
      nodes { id price compareAtPrice }
    }
  }
}

mutation {
  productCreate(input: { title: "Caneca Personalizada", tags: ["promo"] }) {
    product { id }
  }
}

mutation {
  productVariantsBulkCreate(
    productId: "gid://shopify/Product/<id>",
    variants: [
      { price: "29.90", compareAtPrice: "39.90", optionValues: [{ name: "Branca", optionName: "Cor" }] },
      { price: "29.90", optionValues: [{ name: "Preta", optionName: "Cor" }] }
    ]
  ) { productVariants { id } userErrors { field message } }
}

query {
  product(id: "gid://shopify/Product/<id>") {
    title
    variants(first: 5) { nodes { price compareAtPrice } }
  }
}
